contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount <= address(c).balance);

        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBefore = address(c).balance;
        uint thisBefore = address(this).balance;

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cAfter = address(c).balance;
        uint thisAfter = address(this).balance;

        assert(cAfter == cBefore - amount && thisAfter == thisBefore + amount && depositsAfter == depositsBefore);
    }

    receive() external payable {}
}

